 static float Smooth(float a,float b,float v)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,v));
 static float Relief(float x,float z)=>.25f+1.25f*Smooth(-43,-8,x)+1.2f*Smooth(-14,13,z)+.38f*Mathf.Sin((x+42)*.16f)*Mathf.Cos(z*.09f);
 static float OldHeight(float x,float z)=>oldGround.GetInterpolatedHeight((x-ground.transform.position.x)/oldGround.size.x,(z-ground.transform.position.z)/oldGround.size.z)+ground.transform.position.y;
 static float NewHeight(float x,float z){float h=OldHeight(x,z)+Relief(x,z);foreach(var p in pads){float dx=Mathf.Max(0,Mathf.Abs(x-p.bounds.center.x)-p.bounds.extents.x-.3f),dz=Mathf.Max(0,Mathf.Abs(z-p.bounds.center.z)-p.bounds.extents.z-.3f);float d=Mathf.Sqrt(dx*dx+dz*dz);h=Mathf.Lerp(h,p.height,1-Smooth(0,3.2f,d));}return h;}
