 var windowMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));windowMat.name="Interior amber window glass";windowMat.SetColor("_BaseColor",new Color(.7f,.38f,.1f));windowMat.EnableKeyword("_EMISSION");windowMat.SetColor("_EmissionColor",new Color(3.2f,1.5f,.38f));windowMat.globalIlluminationFlags=MaterialGlobalIlluminationFlags.RealtimeEmissive;AssetDatabase.CreateAsset(windowMat,D+"AmberWindow.mat");var frameMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));frameMat.SetColor("_BaseColor",new Color(.085f,.055f,.03f));AssetDatabase.CreateAsset(frameMat,D+"WindowFrame.mat");
 var cookie=new Texture2D(64,64,TextureFormat.RGBA32,false,true);cookie.name="Four pane window cookie";cookie.wrapMode=TextureWrapMode.Clamp;var pixels=new Color[4096];for(int y=0;y<64;y++)for(int x=0;x<64;x++){float value=x<5||x>58||y<5||y>58||Mathf.Abs(x-32)<3||Mathf.Abs(y-32)<3?0:1;pixels[y*64+x]=new Color(value,value,value,value);}cookie.SetPixels(pixels);cookie.Apply();AssetDatabase.CreateAsset(cookie,D+"WindowCookie.asset");int windows=0;
 foreach(var house in buildings){var bounds=BoundsOf(house);var panes=new List<Pane>();foreach(var mf in house.GetComponentsInChildren<MeshFilter>()){var renderer=mf.GetComponent<Renderer>();if(!renderer)continue;var mats=renderer.sharedMaterials;var mesh=mf.sharedMesh;for(int k=0;k<Mathf.Min(mats.Length,mesh.subMeshCount);k++){if(!mats[k]||!mats[k].name.ToLowerInvariant().Contains("window"))continue;mats[k]=windowMat;var vertices=mesh.vertices;var tris=mesh.GetTriangles(k);for(int j=0;j<tris.Length;j+=3){var a=mf.transform.TransformPoint(vertices[tris[j]]);var b=mf.transform.TransformPoint(vertices[tris[j+1]]);var c=mf.transform.TransformPoint(vertices[tris[j+2]]);var normal=Vector3.Cross(b-a,c-a);float area=normal.magnitude*.5f;if(area<.001f)continue;normal.Normalize();var center=(a+b+c)/3;if(Mathf.Abs(normal.y)>.4f)continue;var outward=center-bounds.center;outward.y=0;if(Vector3.Dot(normal,outward)<0)normal=-normal;var pane=panes.FirstOrDefault(p=>Vector3.Dot(p.normal,normal)>.95f&&Vector3.Distance(p.point,center)<1.25f);if(pane==null)panes.Add(new Pane{point=center,normal=normal,area=area});else{pane.point=(pane.point*pane.area+center*area)/(pane.area+area);pane.area+=area;}}}renderer.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);}
