 foreach(var pane in panes.OrderByDescending(p=>p.area).Take(3)){var light=new GameObject("Interior window outward spill").AddComponent<Light>();light.transform.SetParent(house,true);light.transform.position=pane.point-pane.normal*.15f;light.transform.rotation=Quaternion.LookRotation((pane.normal+Vector3.down*.55f).normalized);light.type=LightType.Spot;light.range=8;light.spotAngle=67;light.innerSpotAngle=42;light.color=new Color(1,.66f,.31f);light.intensity=3.5f;light.cookie=cookie;light.shadows=LightShadows.None;var fog=light.gameObject.AddComponent<SettlementFogLight>();fog.source=light;fog.innerRadius=.7f;fog.outerRadius=2.5f;fog.referenceIntensity=3.5f;windows++;}log.AppendLine(house.name+" windowClusters="+panes.Count);}
