 static void Box(Transform parent,string name,Vector3 position,Vector3 scale,Material mat){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.localPosition=position;go.transform.localScale=scale;go.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(go.GetComponent<Collider>());}
 static void OptimizeCopies(Transform player,TerrainData terrain){var textures=new Dictionary<Texture,Texture>();var materials=new Dictionary<Material,Material>();int copied=0;
 Func<Texture,Texture> reduce=tex=>{if(!tex||!(tex is Texture2D)||Mathf.Max(tex.width,tex.height)<=1024)return tex;if(textures.TryGetValue(tex,out var cached))return cached;string source=AssetDatabase.GetAssetPath(tex);var importer=AssetImporter.GetAtPath(source) as TextureImporter;if(importer==null)return tex;string dest=AssetDatabase.GenerateUniqueAssetPath(D+"Texture_"+Path.GetFileName(source));if(!AssetDatabase.CopyAsset(source,dest))return tex;var copy=AssetImporter.GetAtPath(dest) as TextureImporter;copy.maxTextureSize=Mathf.Max(1024,Mathf.Min(2048,Mathf.NextPowerOfTwo(Mathf.Max(tex.width,tex.height))/2));var mac=copy.GetPlatformTextureSettings("Standalone");if(mac.overridden){mac.maxTextureSize=copy.maxTextureSize;copy.SetPlatformTextureSettings(mac);}copy.SaveAndReimport();var result=AssetDatabase.LoadAssetAtPath<Texture>(dest);textures[tex]=result;copied++;return result;};
 foreach(var renderer in Object.FindObjectsOfType<Renderer>(true)){if(renderer.transform.IsChildOf(player))continue;var mats=renderer.sharedMaterials;bool changed=false;for(int i=0;i<mats.Length;i++){var original=mats[i];if(!original)continue;if(materials.TryGetValue(original,out var m)){mats[i]=m;changed=true;continue;}var names=original.GetTexturePropertyNames();if(!names.Any(n=>original.GetTexture(n)&&Mathf.Max(original.GetTexture(n).width,original.GetTexture(n).height)>1024))continue;m=new Material(original);foreach(var name in names)m.SetTexture(name,reduce(original.GetTexture(name)));AssetDatabase.CreateAsset(m,AssetDatabase.GenerateUniqueAssetPath(D+"Mat_"+original.name+".mat"));materials[original]=m;mats[i]=m;changed=true;}if(changed){renderer.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);}string lower=renderer.name.ToLowerInvariant();if(new[]{"grass","fern","mugwort","leaves","bush"}.Any(lower.Contains))renderer.shadowCastingMode=ShadowCastingMode.Off;}
 var layers=terrain.terrainLayers;for(int i=0;i<layers.Length;i++){var layer=Object.Instantiate(layers[i]);layer.diffuseTexture=reduce(layer.diffuseTexture) as Texture2D;layer.normalMapTexture=reduce(layer.normalMapTexture) as Texture2D;layer.maskMapTexture=reduce(layer.maskMapTexture) as Texture2D;AssetDatabase.CreateAsset(layer,AssetDatabase.GenerateUniqueAssetPath(D+"Layer_"+layer.name+".terrainlayer"));layers[i]=layer;}terrain.terrainLayers=layers;
 var holder=Object.FindObjectOfType<FogDemoPipeline>();string pipe=AssetDatabase.GenerateUniqueAssetPath(D+"TerracedPipeline.asset");AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(holder.pipeline),pipe);var asset=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(pipe);var so=new SerializedObject(asset);so.FindProperty("m_RenderScale").floatValue=.9f;so.FindProperty("m_ShadowDistance").floatValue=55;so.FindProperty("m_MainLightShadowmapResolution").intValue=2048;so.FindProperty("m_AdditionalLightsShadowmapResolution").intValue=1024;so.ApplyModifiedPropertiesWithoutUndo();holder.pipeline=asset;EditorUtility.SetDirty(asset);log.AppendLine("copied downscaled environment textures="+copied+" material copies="+materials.Count+" renderScale=.9 shadowDistance=55 mainShadow=2048 additionalShadow=1024");}
